class IndependentSpyAaplStrategies(QCAlgorithm):
    AAPL_RED_DAYS = 3

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = RollingWindow[float](101)
        self.spy_lot = 0

        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_lot = 0

    def OnData(self, data: Slice):
        bars = data.Bars

        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if bars.ContainsKey(spy):
            self.spy_closes.Add(float(bars[spy].Close))

        if bars.ContainsKey(aapl):
            aapl_close = float(bars[aapl].Close)
            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(bars[aapl].EndTime, aapl_close)

        if not all(bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if self.spy_closes.IsReady:
            spy_close = self.spy_closes[0]
            spy_sma_today = sum(self.spy_closes[i] for i in range(100)) / 100.0
            spy_close_yesterday = self.spy_closes[1]
            spy_sma_yesterday = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0

            if self.spy_lot > 0:
                if (spy_close_yesterday >= spy_sma_yesterday
                        and spy_close < spy_sma_today):
                    self.MarketOrder(spy, -self.spy_lot)
                    self.spy_lot = 0
            elif (spy_close_yesterday <= spy_sma_yesterday
                  and spy_close > spy_sma_today):
                quantity = self.CalculateOrderQuantity(spy, 0.40)
                if quantity > 0:
                    self.MarketOrder(spy, quantity)
                    self.spy_lot = quantity

        if self.aapl_rsi.IsReady:
            if self.aapl_lot > 0:
                if self.aapl_rsi.Current.Value > 60:
                    self.MarketOrder(aapl, -self.aapl_lot)
                    self.aapl_lot = 0
            elif self.aapl_red_streak >= self.AAPL_RED_DAYS:
                cash_to_invest = 20_000
                if self.Portfolio.Cash >= cash_to_invest:
                    quantity = int(cash_to_invest // float(bars[aapl].Close))
                    if quantity > 0:
                        self.MarketOrder(aapl, quantity)
                        self.aapl_lot = quantity

