class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=100)
        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0
        self.pending_strategy = {}

    def OnData(self, data: Slice):
        spy_symbol = self.symbols["SPY"]
        if data.Splits.ContainsKey(spy_symbol):
            split = data.Splits[spy_symbol]
            if split.Type == SplitType.SplitOccurred and self.strategy_a_shares > 0:
                self.strategy_a_shares = int(
                    round(self.strategy_a_shares / float(split.SplitFactor))
                )

        aapl_symbol = self.symbols["AAPL"]
        if data.Splits.ContainsKey(aapl_symbol):
            split = data.Splits[aapl_symbol]
            if split.Type == SplitType.SplitOccurred and self.strategy_b_shares > 0:
                self.strategy_b_shares = int(
                    round(self.strategy_b_shares / float(split.SplitFactor))
                )

        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        spy_close = None
        spy_sma = None
        spy_crosses_above = False
        spy_crosses_below = False
        if "SPY" in bars:
            spy_close = bars["SPY"].Close
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == 100:
                spy_sma = sum(self.spy_closes) / 100
                if self.spy_previous_sma is not None:
                    spy_crosses_above = (
                        self.spy_previous_close <= self.spy_previous_sma
                        and spy_close > spy_sma
                    )
                    spy_crosses_below = (
                        self.spy_previous_close >= self.spy_previous_sma
                        and spy_close < spy_sma
                    )
                self.spy_previous_close = spy_close
                self.spy_previous_sma = spy_sma

        if "AAPL" in bars:
            aapl_bar = bars["AAPL"]
            aapl_close = aapl_bar.Close
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)

        if len(bars) != len(self.symbols):
            return

        # Sells are evaluated before buys. Each strategy's pending order also
        # keeps its private lot from issuing a second order before the first fills.
        if self.strategy_a_shares > 0 and not self._has_pending("A"):
            if spy_sma is not None and spy_crosses_below:
                ticket = self.MarketOrder(
                    self.symbols["SPY"], -self.strategy_a_shares, tag="Strategy A sell"
                )
                self.pending_strategy[ticket.OrderId] = "A"

        if self.strategy_b_shares > 0 and not self._has_pending("B"):
            if self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
                ticket = self.MarketOrder(
                    self.symbols["AAPL"], -self.strategy_b_shares, tag="Strategy B sell"
                )
                self.pending_strategy[ticket.OrderId] = "B"

        if self.strategy_a_shares == 0 and not self._has_pending("A"):
            if spy_sma is not None and spy_crosses_above:
                quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
                if quantity > 0:
                    ticket = self.MarketOrder(
                        self.symbols["SPY"], quantity, tag="Strategy A buy"
                    )
                    self.pending_strategy[ticket.OrderId] = "A"

        if self.strategy_b_shares == 0 and not self._has_pending("B"):
            if self.aapl_rsi.IsReady and self.aapl_red_streak >= 1:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20_000:
                    quantity = int(20_000 // bars["AAPL"].Close)
                    if quantity > 0:
                        ticket = self.MarketOrder(
                            self.symbols["AAPL"], quantity, tag="Strategy B buy"
                        )
                        self.pending_strategy[ticket.OrderId] = "B"

    def _has_pending(self, strategy):
        return strategy in self.pending_strategy.values()

    def OnOrderEvent(self, order_event: OrderEvent):
        strategy = self.pending_strategy.get(order_event.OrderId)
        if strategy is None:
            return

        if order_event.FillQuantity != 0:
            if strategy == "A":
                self.strategy_a_shares += order_event.FillQuantity
            else:
                self.strategy_b_shares += order_event.FillQuantity

        if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            del self.pending_strategy[order_event.OrderId]

