class ParallelSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_sma = self.sma(self.symbols["SPY"], 100, Resolution.DAILY)
        self.aapl_rsi = self.rsi(
            self.symbols["AAPL"],
            14,
            MovingAverageType.WILDERS,
            Resolution.DAILY,
        )

        self.previous_closes = {}
        self.previous_spy_sma = None
        self.aapl_red_streak = 0
        self.spy_lot = 0
        self.aapl_lot = 0

        self.set_warm_up(101, Resolution.DAILY)

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        previous_aapl_close = self.previous_closes.get("AAPL")
        if "AAPL" in bars and previous_aapl_close is not None:
            if bars["AAPL"].close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        current_spy_sma = self.spy_sma.current.value if self.spy_sma.is_ready else None

        if (
            len(bars) == len(self.symbols)
            and not self.is_warming_up
            and self._all_state_is_ready()
        ):
            self._run_strategy_a(bars["SPY"], current_spy_sma)
            self._run_strategy_b(bars["AAPL"])

        for ticker, bar in bars.items():
            self.previous_closes[ticker] = bar.close
        if current_spy_sma is not None:
            self.previous_spy_sma = current_spy_sma

    def _all_state_is_ready(self):
        return (
            self.spy_sma.is_ready
            and self.aapl_rsi.is_ready
            and self.previous_spy_sma is not None
            and len(self.previous_closes) == len(self.symbols)
        )

    def _run_strategy_a(self, spy_bar, current_sma):
        previous_close = self.previous_closes["SPY"]

        if self.spy_lot > 0:
            crossed_below = (
                previous_close >= self.previous_spy_sma
                and spy_bar.close < current_sma
            )
            if crossed_below:
                self.market_order(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0

        if self.spy_lot == 0:
            crossed_above = (
                previous_close <= self.previous_spy_sma
                and spy_bar.close > current_sma
            )
            if crossed_above:
                quantity = int(
                    (self.portfolio.total_portfolio_value * 0.40) / spy_bar.close
                )
                if quantity > 0:
                    self.market_order(self.symbols["SPY"], quantity)
                    self.spy_lot = quantity

    def _run_strategy_b(self, aapl_bar):
        if self.aapl_lot > 0 and self.aapl_rsi.current.value > 60:
            self.market_order(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            cash_to_invest = 20_000
            if self.portfolio.cash >= cash_to_invest:
                quantity = int(cash_to_invest / aapl_bar.close)
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

