                if quantity > 0:
                    self.MarketOrder(spy, quantity, tag="Strategy A buy")
                    self.spy_lot = quantity

            if (
                self.aapl_lot == 0
                and self.aapl_rsi.IsReady
                and self.previous_close[aapl] is not None
                and self.aapl_red_streak >= 1
                and float(self.Portfolio.Cash) >= 20_000.0
            ):
                quantity = floor(20_000.0 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(aapl, quantity, tag="Strategy B buy")
                    self.aapl_lot = quantity

