class ParallelSpyAaplStrategy(QCAlgorithm):
    RED_DAYS_REQUIRED = 1

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy_closes = deque(maxlen=100)
        self.previous_spy_above_sma = None
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.Wilders
        )

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(spy):
            spy_close = data.Bars[spy].Close
            self.spy_closes.append(spy_close)
        else:
            spy_close = None

        if data.Bars.ContainsKey(aapl):
            aapl_bar = data.Bars[aapl]
            aapl_close = aapl_bar.Close
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)
        else:
            aapl_close = None

        all_bars_present = all(
            data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )

        spy_above_sma = None
        if spy_close is not None and len(self.spy_closes) == 100:
            spy_sma = sum(self.spy_closes) / 100
            spy_above_sma = spy_close > spy_sma

        if not all_bars_present:
            if spy_above_sma is not None:
                self.previous_spy_above_sma = spy_above_sma
            return

        if not self.aapl_rsi.IsReady or spy_above_sma is None:
            self.previous_spy_above_sma = spy_above_sma
            return

        # Sells are evaluated before buys.
        if self.Portfolio[spy].Invested:
            crossed_below = (
                self.previous_spy_above_sma is True
                and not spy_above_sma
            )
            if crossed_below:
                self.Liquidate(spy, "SPY crossed below its 100-day SMA")

        if self.Portfolio[aapl].Invested:
            if self.aapl_rsi.Current.Value > 60:
                self.Liquidate(aapl, "AAPL RSI(14) closed above 60")

        if not self.Portfolio[spy].Invested:
            crossed_above = (
                self.previous_spy_above_sma is False
                and spy_above_sma
            )
            if crossed_above:
                self.SetHoldings(
                    spy, 0.40, tag="SPY crossed above its 100-day SMA"
                )

        if not self.Portfolio[aapl].Invested:
            if self.aapl_red_streak >= self.RED_DAYS_REQUIRED:
                cash_required = 20_000
                if self.Portfolio.Cash >= cash_required:
                    quantity = floor(cash_required / aapl_close)
                    if quantity > 0:
                        self.MarketOrder(
                            aapl,
                            quantity,
                            tag="AAPL consecutive red days",
                        )

        self.previous_spy_above_sma = spy_above_sma

