class ParallelSpyAaplStrategy(QCAlgorithm):
    RED_DAYS_REQUIRED = 3

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = RollingWindow[float](101)
        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = self.RSI(
            self.symbols["AAPL"], 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        if "SPY" in bars:
            spy_close = float(bars["SPY"].Close)
            self.spy_closes.Add(spy_close)
            if self.spy_closes.Count >= 101:
                self.previous_spy_close = float(self.spy_closes[1])
                self.previous_spy_sma = sum(
                    float(self.spy_closes[i]) for i in range(1, 101)
                ) / 100.0

        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].Close)
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_close

        if len(bars) != len(self.symbols):
            return

        self._run_spy_strategy(float(bars["SPY"].Close))
        self._run_aapl_strategy(float(bars["AAPL"].Close))

    def _run_spy_strategy(self, close):
        if self.spy_closes.Count < 101:
            return

        today_sma = sum(float(self.spy_closes[i]) for i in range(100)) / 100.0
        crosses_above = (
            self.previous_spy_close <= self.previous_spy_sma
            and close > today_sma
        )
        crosses_below = (
            self.previous_spy_close >= self.previous_spy_sma
            and close < today_sma
        )

        symbol = self.symbols["SPY"]
        if self.spy_lot > 0:
            if crosses_below:
                self.MarketOrder(symbol, -self.spy_lot)
                self.spy_lot = 0
        elif crosses_above:
            quantity = self.CalculateOrderQuantity(symbol, 0.40)
            if quantity > 0:
                self.MarketOrder(symbol, quantity)
                self.spy_lot = quantity

    def _run_aapl_strategy(self, close):
        if not self.aapl_rsi.IsReady:
            return

        symbol = self.symbols["AAPL"]
        if self.aapl_lot > 0:
            if float(self.aapl_rsi.Current.Value) > 60.0:
                self.MarketOrder(symbol, -self.aapl_lot)
                self.aapl_lot = 0
        elif self.aapl_red_streak >= self.RED_DAYS_REQUIRED:
            cash_required = 20_000.0
            if float(self.Portfolio.Cash) >= cash_required:
                quantity = int(cash_required // close)
                if quantity > 0:
                    self.MarketOrder(symbol, quantity)
                    self.aapl_lot = quantity

